package ci_test

import (
	"encoding/base64"
	"testing"
	"time"

	"github.com/myguard-labs/mailstrix/internal/extract"
)

// AUD-17b: the 7z LZMA2 dictionary is bounded at 64 MiB (lzma2DictCeiling) (internal/extract/lzma2cap.go).
// Fixtures were generated with p7zip 7z; each payload is 'A' repeated with the
// marker overwriting its tail (python: b[n-len(m):]=m):
//
//	over: solid 5 x 14 MiB members (70 MiB folder; each member is under the
//	      16 MiB member cap, effective dict min(96m,70m) > 64 MiB), members
//	      LZ2-MARKER-over{,2..5}.bin 'A'-filled, 7z a -m0=lzma2:d=128m -mmt=1 -ms=on over.7z LZ2-MARKER-over*.bin
//	      (7z l -slt: Method = LZMA2:96m, Solid = +)
//	edge: 16 MiB, 7z a -m0=lzma2:d=64m -mmt=1 edge.7z LZ2-MARKER-edge.bin (7z l -slt: LZMA2:24 = 16 MiB dict; below the ceiling, not at it)
//	in:   1 MiB, 7z a -m0=lzma2:d=8m  -mmt=1 in.7z   LZ2-MARKER-in.bin
//	def:  64 KiB, 7z a def.7z LZ2-MARKER-def.bin  (7-Zip default settings)
const (
	lzma2OverB64 = ""
	lzma2EdgeB64 = ""
	lzma2InB64   = ""
	lzma2DefB64  = ""
)

func lzma2Fixture(t *testing.T, s string) []byte {
	t.Helper()
	b, err := base64.StdEncoding.DecodeString(s)
	if err != nil {
		t.Fatal(err)
	}
	return b
}

func TestLZMA2DictCap(t *testing.T) {
	t.Cleanup(extract.SetDecryptAttemptTimeForTest(time.Minute))
	run := func(name, b64, marker string, wantCap bool) {
		t.Run(name, func(t *testing.T) {
			res := extract.ExtractWithOptions(lzma2Fixture(t, b64), extract.FullOptions(time.Time{}))
			if got := hasStopKind(res, "lzma-dict"); got != wantCap {
				t.Fatalf("lzma-dict cap=%v want %v: %v", got, wantCap, res.CapHits)
			}
			if got := hasStreamWith(res, []byte(marker)); got == wantCap {
				t.Fatalf("stream present=%v with cap=%v", got, wantCap)
			}
		})
	}
	run("over ceiling refused", lzma2OverB64, "LZ2-MARKER-over", true)
	run("16 MiB member with d=64m request extracts (7-Zip clamps the dict to 16 MiB; exact 64 MiB bound is unit-tested in lzma2cap_test.go)", lzma2EdgeB64, "LZ2-MARKER-edge", false)
	run("in ceiling control", lzma2InB64, "LZ2-MARKER-in", false)
	run("7-Zip default small data", lzma2DefB64, "LZ2-MARKER-def", false)
}
